var AIChatBot=AIChatBot||(function(){console.log("chatbot");let specialisation="";const app=$ui.getApp();let addImgVisible=true;let takeImgVisible=true;let SpeechVisible=true;let historicObject;let currentTools=null;let id=null;function render(params,isAdaContext,spe,dataDisclaimer,convId){let ctn=params[0];id=convId;if(!ctn)ctn=$('#AIchatbot');if(dataDisclaimer){$(ctn).find('#data_warn').html(dataDisclaimer);$(ctn).find('#data_warn').show();}
specialisation=spe;ctn.querySelector('#chatbot_input_message').addEventListener('keyup',function(event){if(event.key==='Enter'&&event.target.matches('#chatbot_input_message')){chatbotSendMessage(ctn);}});if(AiJsTools){AiJsTools.addChatOption(ctn.querySelector('.ai-user-input'),addImgVisible,takeImgVisible,SpeechVisible);}else{console.log("cannot loaded AiJsTools");}
ctn.querySelector('#chatbot_send_button').onclick=function(){AIChatBot.chatbotSendMessage(ctn);};if(isAdaContext){historicObject=app.getBusinessObject("AdaPromptHistory");historicObject.getForCreate(createHistoric);}}
function createHistoric(item){historicObject.save((newItem)=>{},item);}
function chatbotSendMessage(ctn){let chatMessages=ctn.querySelector('#chatbot_messages');desableChatbot(ctn);if(!id)(ctn).find(".user-messages").each(function(){let text={};text.role="user";text.content=$(this).find(".msg").text();historic.push(JSON.stringify(text));text={};text.role="assistant";text.content=$(this).nextAll(".bot-messages").first().find(".msg").text();historic.push(JSON.stringify(text));});let postParams;if(AiJsTools){postParams=AiJsTools.getPostParams(ctn,specialisation,id);}else{console.log("ERROR no AiJsTools");}
if(AiJsTools){chatMessages.append(AiJsTools.getDisplayUserMessage(ctn));chatMessages.append(AiJsTools.getDisplayBotMessage());}
if(AiJsTools){AiJsTools.resetInput(ctn.querySelector('.ai-chat-input-area'));}else{ctn.querySelector('#chatbot_input_message').value='';}
chatMessages.scrollTop=chatMessages.scrollHeight;AiJsTools.callApi(AiJsTools.apiName,"POST",postParams,function(botResponse){parseResponseAndDisplay(botResponse,ctn,postParams);});}
function parseResponseAndDisplay(botResponse,ctn,postParams){let userMessage=ctn.querySelector('#chatbot_input_message').value;let chatMessages=ctn.querySelector('#chatbot_messages');let userImg=$(ctn).find("#input-img img")?.attr("src");if(botResponse.hasOwnProperty('type')&&botResponse.type=='error'){displayAnswer("Sorry, an error occurred",ctn);addHistoric(userMessage,"Sorry, an error occurred",null,null,$grant.getLogin());}else if(botResponse.tools&&botResponse.tools.length>0){const tools=botResponse.tools||botResponse.response?.tools||[];addToolsDialog(ctn,tools,postParams,botResponse);}else{let result=botResponse.response.choices[0].message.content;result=escapeHtml(result);$view.markdownToHTML(result,0,resulthtml=>{displayAnswer(resulthtml,ctn);addHistoric(userMessage,result,userImg,botResponse.response.usage,$grant.getLogin());});}
enableChatbot(ctn);chatMessages.scrollTop=chatMessages.scrollHeight;}
function displayAnswer(html,ctn){const $lastBot=$(ctn).find(".bot-messages").last();const $msg=$lastBot.find("span.msg");if($lastBot.length&&$lastBot.next().hasClass("tools")){$lastBot.remove();$(ctn).find(".tools").last().after($("<div/>").addClass("bot-messages").append($("<span/>").addClass("msg").html(html)));}else{$msg.html(html);}}
function addToolsDialog(ctn,tools,postParams,botResponse){currentTools={};if(tools.length==0)return;const isFr=$grant.langiso=="fr";const toolTag=isFr?"Outil":"Tool";const $toolsBox=$("<div/>").addClass("tools tools-per-tool");console.log("tools",tools);tools.forEach(tool=>{const toolName=tool?.function?.name||tool?.description||"";const toolId=tool?.id||toolName;currentTools[toolId]={response:null,tool:tool};const detailText=formatToolAsk($T("AI_TOOL_ASK"),tool?.function?.arguments,toolName);const $bar=$("<div/>").addClass("ai-tool-bar");const $label=$("<div/>").addClass("ai-tool-bar-label");$label.append($("<span/>").addClass("ai-tool-bar-tag").text(toolTag));$label.append($("<span/>").addClass("ai-tool-bar-name").text(detailText||"—"));const $actions=$("<div/>").addClass("ai-tool-actions").attr("data-tool-name",toolName).attr("id",toolId);const $btnRefuse=$("<button/>",{type:"button"}).addClass("ai-tool-btn ai-tool-btn-outline").attr("title",isFr?"Refuser l'exécution de l'outil":"Refuse tool execution").attr("aria-label",isFr?"Refuser l'exécution de l'outil":"Refuse tool execution").append($("<i/>").addClass("fa fa-times").attr("aria-hidden","true")).on("click",function(e){e.preventDefault();console.log("refuse tool",tool);refuseTool(tool,$actions,isFr,ctn,postParams);});const $btnAccept=$("<button/>",{type:"button"}).addClass("ai-tool-btn ai-tool-btn-outline ai-tool-bar-accept").attr("aria-label",isFr?"Autoriser l'exécution des outils":"Allow tools to run").attr("title",isFr?"Autoriser l'exécution des outils":"Allow tools to run").append($("<i/>").addClass("fa fa-check").attr("aria-hidden","true")).on("click",function(e){e.preventDefault();acceptTool(tool,$actions,isFr,ctn,postParams);});$actions.append($btnRefuse,$btnAccept);$bar.append($label,$actions);$toolsBox.append($bar);});const $lastBot=$(ctn).find(".bot-messages").last();const $toolsAfterLastBot=$lastBot.nextAll(".tools").last();if($lastBot.length&&$toolsAfterLastBot.length>0){const $lastToolBlock=$(ctn).find(".tools").last();$toolsBox.addClass("tools-below");$lastToolBlock.after($toolsBox);}else{const botmessage=botResponse?.response?.choices[0]?.message?.content;const botHint=getHint(botmessage,isFr);$lastBot.find("span.msg").empty().text(botHint);$toolsBox.addClass("tools-below");$lastBot.after($toolsBox);}
console.log("addToolsDialog $toolsBox",currentTools);}
function getHint(botmessage,isFr){console.log("getHint botmessage",botmessage);if(botmessage&&botmessage!=""){return botmessage;}
return isFr?"Des outils sont proposés ci-dessous.":"Tools are proposed below.";}
function refuseTool(tool,ctn,isFr,ctnGlobal,postParams){const toolName=ctn?.attr("data-tool-name");const toolId=ctn?.attr("id")||toolName;currentTools[toolId].response="refused";const $iconRefused=$("<i/>").addClass("fa fa-times").attr("aria-hidden","true").attr("aria-label",isFr?"Outil refusé":"Tool refused").attr("title",isFr?"Outil refusé":"Tool refused");ctn.html("");ctn.removeClass("ai-tool-actions");ctn.addClass("ai-tool-state");ctn.append($iconRefused);if(isAllToolsAnswered()){callApiWithAcceptedTools(postParams,ctnGlobal);}}
function acceptTool(tool,ctn,isFr,ctnGlobal,postParams){console.log("acceptTool tool",currentTools);const toolName=ctn?.attr("data-tool-name");const toolId=ctn?.attr("id")||toolName;currentTools[toolId].response="accepted";const $iconAccepted=$("<i/>").addClass("fa fa-check").attr("aria-hidden","true").attr("aria-label",isFr?"Outil accepté":"Tool accepted").attr("title",isFr?"Outil accepté":"Tool accepted");ctn.append($iconAccepted);ctn.html("");ctn.removeClass("ai-tool-actions");ctn.addClass("ai-tool-state");ctn.append($iconAccepted);if(isAllToolsAnswered()){callApiWithAcceptedTools(postParams,ctnGlobal);}}
function isAllToolsAnswered(){for(let toolId in currentTools){if(currentTools[toolId].response===null){return false;}}
return true;}
function callApiWithAcceptedTools(postParams,ctnGlobal){let acceptedTools=[];let refusedTools=[];for(let toolId in currentTools){if(currentTools[toolId].response==="accepted"){acceptedTools.push(currentTools[toolId].tool);}else{refusedTools.push(currentTools[toolId].tool);}}
AiJsTools.callApiWithTools(postParams,acceptedTools,refusedTools,function(response){parseResponseAndDisplay(response,ctnGlobal,postParams);});currentTools=null;}
function escapeHtml(text){if(!text)return"";let map={'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'};return String(text??'').replaceAll(/[&<>"']/g,function(m){return map[m];});}
function desableChatbot(ctn){$(ctn).find("#chatbot_send_button").prop("disabled",true);$(ctn).find("#chatbot_input_message").prop("disabled",true);}
function enableChatbot(ctn){$(ctn).find("#chatbot_send_button").prop("disabled",false);$(ctn).find("#chatbot_input_message").prop("disabled",false);}
function formatToolAsk(template,param,toolName){let formattedParam=param;if(param){try{const json=JSON.parse(param);if(typeof json==='object'&&json!==null&&!Array.isArray(json)){formattedParam=Object.entries(json).map(([key,value])=>`${key}: ${value}`).join(', ');}}catch(e){console.error("param is not valid JSON",e);}}
return template.replaceAll('[TOOL]',toolName).replaceAll('[PARAMS]',formattedParam).replaceAll(/\[PARAMS\?:(.*)\]/g,formattedParam?'$1':'');}
function addHistoric(userMessage,botMessage,userImg,cost,login){if(!historicObject)return;let promptHist=$app.getBusinessObject("AdaPromptsLogger");promptHist.getForCreate((item)=>{item.adaPlogPhyId=historicObject.getRowId();item.adaPlogPrompt=userMessage;item.adaPlogResponse=botMessage;item.adaPlogCost=cost;if(userImg)item.adaPlogImage=userImg;AiJsTools.callApi("AdaSavePrompt","POST",{obj:item},function(botResponse){if(botResponse.hasOwnProperty('type')&&botResponse.type=='error'){console.log("error prompt save",botResponse);}else{console.log("prompt saved");}});});}
return{render:render,chatbotSendMessage:chatbotSendMessage};})();